<?php
namespace App\Libraries;

final class LatenessReportDelivery
{
    private $db;private $send;private bool $real;private string $base;
    public function __construct($db=null,?callable $send=null,?string $base=null){$this->db=$db??db_connect();$this->real=$send===null;$this->base=$base??base_url();$this->send=$send??static fn($phone,$text,$url,$filename)=>(new WhatsAppGateway())->request($phone,$text,'document',$url,$filename);}
    public function send(int $class,string $format,string $number,int $owner,string $recipient=''): array
    {
        $format=strtolower($format);if(!in_array($format,['excel','pdf'],true))throw new \InvalidArgumentException('Pilih format Excel atau PDF.');
        $phone=WhatsAppGateway::phone($number);if(!$phone)throw new \InvalidArgumentException('Nomor WhatsApp tujuan tidak valid.');$recipient=trim($recipient);if(mb_strlen($recipient)>180)throw new \InvalidArgumentException('Nama penerima terlalu panjang.');
        $db=$this->db;$klass=$db->table('kelas')->select('id,nama_kelas')->where(['id'=>$class,'wali_kelas_id'=>$owner])->get()->getRowArray();if(!$klass)throw new \InvalidArgumentException('Kelas tidak dapat diakses.');
        $host=strtolower((string)parse_url($this->base,PHP_URL_HOST));if(!in_array(parse_url($this->base,PHP_URL_SCHEME),['http','https'],true)||!$host||in_array($host,['localhost','::1','[::1]','0.0.0.0'],true)||str_starts_with($host,'127.'))throw new \InvalidArgumentException('Gateway memerlukan alamat aplikasi publik untuk mengambil berkas. Pengiriman tersedia pada VPS.');
        if($this->real&&!(new WhatsAppGateway())->configured())throw new \InvalidArgumentException('Gateway WhatsApp belum siap. Periksa menu WhatsApp Gateway.');
        $rows=LatenessReportExport::rows($class);$now=new \DateTimeImmutable('now',new \DateTimeZone('Asia/Jakarta'));$stamp=$now->format('d-m-Y H:i:s');$extension=$format==='excel'?'xls':'pdf';$token=bin2hex(random_bytes(32));$file=bin2hex(random_bytes(32)).'.'.$extension;$path=WRITEPATH.'status-kedisiplinan/'.$file;
        $bytes=$format==='excel'?LatenessReportExport::excel($rows,$klass['nama_kelas'],$stamp):LatenessReportExport::pdf($rows,$klass['nama_kelas'],$stamp);$filename='Status-Keterlambatan-'.preg_replace('/[^A-Za-z0-9_-]/','-',$klass['nama_kelas']).'.'.$extension;$title=$format==='excel'?'Excel':'PDF';$text='Berikut hasil export Status Kedisiplinan Keterlambatan kelas '.$klass['nama_kelas'].' dalam format '.$title.'. Data memuat jumlah, tanggal, alasan, dan status keterlambatan siswa. Dibuat '.$stamp.' WIB.';$snapshot=hash('sha256',json_encode([$klass,$rows,$format],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));$key=hash('sha256',implode('|',[$owner,$class,$phone,$snapshot]));$db->transBegin();
        try{$db->query('SELECT id FROM kelas WHERE id=? AND wali_kelas_id=? FOR UPDATE',[$class,$owner]);$existing=$db->table('status_kedisiplinan_pengiriman')->where('session_key',$key)->get()->getRowArray();if($existing){$db->transCommit();return ['ok'=>$existing['status']==='sent','status'=>$existing['status'],'already'=>true,'message'=>$existing['status']==='sent'?'Export yang sama sudah diterima gateway untuk nomor ini.':'Export ini pernah atau sedang diproses. Periksa Komunikasi sebelum mengirim ulang.'];}
            if(!is_dir(dirname($path))&&!mkdir(dirname($path),0770,true)&&!is_dir(dirname($path)))throw new \RuntimeException('Folder ekspor belum tersedia.');if(file_put_contents($path,$bytes,LOCK_EX)!==strlen($bytes))throw new \RuntimeException('Berkas ekspor gagal disimpan.');
            $db->table('pesan_komunikasi')->insert(['kelas_id'=>$class,'pengirim'=>'AIWalas','penerima'=>$recipient?:$phone,'nomor_tujuan'=>$phone,'isi_pesan'=>$text,'kategori'=>'Export Status Kedisiplinan '.$title,'status_pengiriman'=>'Disiapkan','dibuat_oleh'=>$owner]);$message=$db->insertID();$db->table('status_kedisiplinan_pengiriman')->insert(['session_key'=>$key,'kelas_id'=>$class,'owner_id'=>$owner,'format'=>$format,'nomor_tujuan'=>$phone,'berkas'=>$file,'token_hash'=>hash('sha256',$token),'berlaku_sampai'=>$now->modify('+24 hours')->format('Y-m-d H:i:s'),'message_id'=>$message,'status'=>'processing','dibuat_pada'=>$now->format('Y-m-d H:i:s')]);$dispatch=$db->insertID();if(!$db->transStatus())throw new \RuntimeException('Pengiriman belum dapat dicatat.');$db->transCommit();
        }catch(\Throwable $error){$db->transRollback();if(is_file($path))unlink($path);throw $error;}
        $status='unknown';$note='Gateway belum mengonfirmasi hasil. Periksa Komunikasi sebelum mengirim ulang.';try{$response=($this->send)($phone,$text,rtrim($this->base,'/').'/media/status-kedisiplinan/'.$token,$filename);$body=$response['response']??[];$confirmation=$body['status']??$body['success']??null;if(($response['ok']??false)&&in_array($confirmation,[true,1,200,'true','success','sent'],true)){$status='sent';$note='Berkas export diterima gateway.';}elseif(!($response['ok']??false)&&in_array($confirmation,[false,0,'false','error','failed'],true)){$status='failed';$note='Gateway menolak pengiriman berkas export.';}}catch(\Throwable $error){}
        $db->transBegin();$db->table('status_kedisiplinan_pengiriman')->where('id',$dispatch)->update(['status'=>$status,'result_note'=>$note]);$db->table('pesan_komunikasi')->where('id',$message)->update(['status_pengiriman'=>$status==='sent'?'Terkirim':($status==='failed'?'Gagal':'Disiapkan'),'dikirim_pada'=>$status==='sent'?$now->format('Y-m-d H:i:s'):null]);if(!$db->transStatus()){$db->transRollback();throw new \RuntimeException('Hasil pengiriman belum tercatat. Periksa menu Komunikasi.');}$db->transCommit();return ['ok'=>$status==='sent','status'=>$status,'already'=>false,'message'=>$note];
    }
}
